example_item.example_item_data:
new_system('fmt_demo');
add_block('nflow/source/sine', 'fmt_demo/Sine');
add_block('nflow/math/gain', 'fmt_demo/Gain', 'Gain', 2);
add_block('nflow/sink/scope', 'fmt_demo/Scope');
add_line('fmt_demo', 'Sine/1', 'Gain/1');
add_line('fmt_demo', 'Gain/1', 'Scope/1');
set_param('fmt_demo', 'StopTime', 10, 'SampleTime', 0.01);
f = [tempdir(), 'fmt_demo.nflow'];
save_system('fmt_demo', f);
disp(fileread(f));
bdclose('fmt_demo');

new_system('rlc_fmt');
add_block('nflow/acausal_electrical/ConstantVoltage', 'rlc_fmt/V1', 'V', 1);
add_block('nflow/acausal_electrical/Resistor', 'rlc_fmt/R1', 'R', 1);
add_block('nflow/acausal_electrical/Inductor', 'rlc_fmt/L1', 'L', 1, 'i0', 0);
add_block('nflow/acausal_electrical/Capacitor', 'rlc_fmt/C1', 'C', 1, 'v0', 0);
add_block('nflow/acausal_electrical/VoltageSensor', 'rlc_fmt/VS');
add_block('nflow/acausal_electrical/Ground', 'rlc_fmt/G1');
add_block('nflow/acausal_electrical/Ground', 'rlc_fmt/G2');
add_line('rlc_fmt', 'V1/p', 'R1/p');
add_line('rlc_fmt', 'R1/n', 'L1/p');
add_line('rlc_fmt', 'L1/n', 'C1/p');
add_line('rlc_fmt', 'C1/p', 'VS/p');
add_line('rlc_fmt', 'G1/p', 'V1/n');
add_line('rlc_fmt', 'C1/n', 'VS/n');
add_line('rlc_fmt', 'G2/p', 'C1/n');
set_param('rlc_fmt', 'StopTime', 10, 'SampleTime', 0.05, 'Solver', 'dae');
f = [tempdir(), 'rlc_fmt.nflow'];
save_system('rlc_fmt', f);
disp(fileread(f));
bdclose('rlc_fmt');
